@contextmanager
def managed_locks(*locks):
    acquired = []
    try:
        for lock in locks:
            lock.acquire()
            acquired.append(lock)
        yield
    finally:
        for lock in reversed(acquired):
            lock.release()


def normalize_url(url):
    try:
        url = unquote(url.strip())
        if not url.startswith(('http://', 'https://')):
            url = 'https://' + url

        parsed = urlparse(url.lower())

        params_dict = parse_qs(parsed.query, keep_blank_values=True)
        params_tuples = []
        for key in sorted(params_dict.keys()):
            for val in sorted(params_dict[key]):
                params_tuples.append((key, val))

        normalized_query = urlencode(params_tuples) if params_tuples else ""

        normalized_path = parsed.path.rstrip('/')

        normalized = f"{parsed.scheme}://{parsed.netloc}{normalized_path}"
        if normalized_query:
            normalized += f"?{normalized_query}"

        if parsed.fragment:
            normalized += f"#{parsed.fragment}"

        return normalized
    except Exception as e:
        logger.error(f"URL normalization error for {url}: {e}")
        return url.lower()


def get_client_with_retry(max_retries=15):
    for attempt in range(max_retries):
        if client_semaphore.acquire(timeout=45):
            return True
        wait_time = min(2 ** attempt + random.uniform(0, 1), 60)
        logger.warning(f"Client semaphore exhausted, attempt {attempt + 1}/{max_retries}, waiting {wait_time:.1f}s")
        if shutdown_event.is_set():
            return False
        time.sleep(wait_time)
    logger.error(f"Failed to acquire client after {max_retries} retries")
    return False


def release_client():
    try:
        client_semaphore.release()
    except ValueError:
        logger.warning("Attempted to release semaphore more than acquired")


def calculate_content_hash(content):
    try:
        return hashlib.sha256(content.encode('utf-8', errors='ignore')).hexdigest()
