        return None


def estimate_tokens_accurate(text):
    try:
        if not text:
            return 0
        word_count = len(text.split())
        char_count = len(text)
        token_estimate = max(int(word_count * 1.3), int(char_count / 4.0))
        return token_estimate
    except Exception as e:
        logger.error(f"Token estimation error: {e}")
        return 0


def extract_njt_metadata(soup, url):
    metadata = {
        "title": "",
        "law_number": "",
        "law_year": "",
        "law_type": "",
        "date": "",
        "categories": [],
        "section": "",
        "subsection": ""
    }

    try:
        title_tag = soup.find('h1', class_=['jogszabaly-title', 'title', 'cim', 'main-title']) or soup.find('h1')
        if title_tag:
            title_text = title_tag.get_text(strip=True)
            if len(title_text) < 500:
                metadata["title"] = title_text

        if not metadata["title"]:
            title_tag = soup.find('meta', property='og:title')
            if title_tag and title_tag.get('content'):
                metadata["title"] = title_tag.get('content')[:500]

        njt_patterns = [
            r'(\d{4})\.\s*évi\s*([IVXLCDMivxlcdm]+)\.\s*(törvény|rendelet|határozat|végzés|közlemény)',
            r'(\d{4})\s*\.?\s*évi\s*([A-Za-z0-9]+)\s*(törvény|rendelet|határozat)',
            r'(\d{1,4})\s*\.?\s*([A-Za-z0-9]+)\s*sz\.?\s*(törvény|rendelet)'
        ]

        for pattern in njt_patterns:
            match = re.search(pattern, url + " " + metadata.get("title", ""), re.IGNORECASE)
            if match:
                metadata["law_year"] = match.group(1)
                law_type = match.group(3).lower()
                metadata["law_type"] = law_type
                metadata["law_number"] = f"{metadata['law_year']}. évi"
                break

        if '/jogszabaly/' in url:
            metadata["section"] = "jogszabály"
        elif '/indokolasok/' in url:
            metadata["section"] = "indokolás"
        elif '/kozlonyek/' in url:
            metadata["section"] = "közlöny"
        elif '/koltsegvetesi' in url:
            metadata["section"] = "költségvetési"
        elif '/felépítés/' in url or '/felepites/' in url:
            metadata["section"] = "felépítés"
        elif '/nemzetközi' in url:
            metadata["section"] = "nemzetközi"

        date_patterns = [
            r'(\d{4})-(\d{1,2})-(\d{1,2})',
            r'(\d{4})\.\s*(január|február|március|április|május|június|július|augusztus|szeptember|október|november|december)\s*(\d{1,2})',
            r'(\d{1,2})\.\s*(január|február|március|április|május|június|július|augusztus|szeptember|október|november|december)\s*(\d{4})',
        ]

        page_text = soup.get_text()[:5000]
        for pattern in date_patterns:
            match = re.search(pattern, page_text, re.IGNORECASE)
            if match:
                metadata["date"] = match.group(0)
                break

    except Exception as e:
        logger.error(f"Metadata extraction error: {e}")

    return metadata


def clean_njt_content(soup):
    try:
        for tag in soup(['script', 'style', 'noscript', 'nav', 'header', 'footer', 'aside', 'form', 'button', 'meta', 'link']):
            tag.decompose()

        for selector in ['.navbar', '.menu', '.breadcrumb', '.pagination', '.sidebar', '.advertisement', '.ad', '.banner', '.cookie', '.modal']:
            for element in soup.select(selector):
                element.decompose()

        main_content = soup.find('main') or soup.find(['article', 'div'], class_=['content', 'article', 'body', 'main-content', 'jogszabaly-content', 'main', 'container'])

        if main_content:
            content_str = str(main_content)
        else:
            content_str = str(soup.find('body') or soup)

        return content_str
    except Exception as e:
        logger.error(f"Content cleaning error: {e}")
        return str(soup)


def process_with_ultra_quality_ai(url, content, content_type, metadata=None):
    if not get_client_with_retry():
        logger.error(f"Failed to acquire client for {url}")
        return None

    try:
        logger.info(f"AI processing ({content_type}): {url[:70]}")

        content_clean = content.strip() if content else ""

        if len(content_clean) < 400:
            logger.warning(f"Content too short ({len(content_clean)} chars): {url[:60]}")
            return None

        if len(content_clean) > 100000:
            content_clean = content_clean[:100000]

        metadata_str = ""
        if metadata and any(metadata.values()):
            metadata_parts = []
            if metadata.get('title'):
                metadata_parts.append(f"Cím: {metadata['title'][:200]}")
            if metadata.get('law_number'):
                metadata_parts.append(f"Jogszabály száma: {metadata['law_number']}")
            if metadata.get('law_type'):
                metadata_parts.append(f"Típus: {metadata['law_type']}")
            if metadata.get('date'):
                metadata_parts.append(f"Dátum: {metadata['date']}")
            if metadata.get('section'):
                metadata_parts.append(f"Szekció: {metadata['section']}")

            if metadata_parts:
                metadata_str = "JOGSZABÁLYI METAADATOK:\n" + "\n".join(metadata_parts) + "\n"

        if content_type == "pdf":
            system_prompt = "Te a Nemzeti Jogszabálytár legfejlettebb PDF feldolgozó AI-ja vagy. Feladata: világos, strukturált, teljes, pontosan formázott magyar jogi tartalom előállítása. KÖTELEZŐEN: 1. Teljes és pontos szöveg megtartása 2. Markdown szerkezet (fejlécek, listák, táblázatok) 3. Jogi terminológia megtartása 4. Nulla információ vesztés 5. Hivatkozások és kapcsolatok megőrzése 6. Tagolt, olvasható formátum. OUTPUT: Strukturált markdown formátum magyar jogszabályi tartalommal."
            user_prompt = f"Dolgozd fel ezt a jogi PDF-tartalmat teljes, pontos, strukturált magyar jogi dataset szintjén:\n{metadata_str}\nURL: {url}\nPDF TARTALOM:\n{content_clean}\n\nFELADAT: Teljes, pontos, világos magyar jogi training data struktúrában."
        else:
            system_prompt = "Te a Nemzeti Jogszabálytár legfejlettebb HTML feldolgozó AI-ja vagy. Feladata: tiszta, strukturált, teljes jogi webtartalom feldolgozása. KÖTELEZŐEN: 1. Csak jogi tartalom 2. Markdown formátum 3. Teljes pontosság 4. Terminológia megtartása 5. Nulla navigáció/reklám. OUTPUT: Strukturált, tiszta jogi tartalom markdown-ban."
            user_prompt = f"Dolgozd fel ezt a jogi webtartalmat world-class minőségben:\n{metadata_str}\nURL: {url}\nHTML TARTALOM:\n{content_clean}\n\nFELADAT: Tiszta, teljes, strukturált jogi training data."

        models_config = [
            {"model": "qwen-3-coder-480b", "max_tokens": 50000, "temp": 0.05},
            {"model": "gpt-oss-120b", "max_tokens": 65536, "temp": 0.05},
            {"model": "qwen-3-32b", "max_tokens": 20000, "temp": 0.05}
        ]

        for model_config in models_config:
            if shutdown_event.is_set():
                return None

            client_idx = random.randint(0, len(clients) - 1)

            for retry in range(4):
                try:
                    client = clients[client_idx]
                    extra_params = {}
                    if model_config["model"] == "gpt-oss-120b":
                        extra_params["reasoning_effort"] = "medium"

                    stream = client.chat.completions.create(
                        messages=[
                            {"role": "system", "content": system_prompt},
                            {"role": "user", "content": user_prompt}
                        ],
                        model=model_config["model"],
                        stream=True,
                        max_completion_tokens=model_config["max_tokens"],
                        temperature=model_config["temp"],
                        top_p=0.95,
                        timeout=ai_processing_timeout,
                        **extra_params
                    )

                    cleaned_content = ""
                    chunk_count = 0
                    for chunk in stream:
                        if shutdown_event.is_set():
                            return None

                        content_chunk = chunk.choices[0].delta.content if chunk.choices[0].delta.content else ""
                        cleaned_content += content_chunk
                        chunk_count += 1

                        if chunk_count % 100 == 0:
                            gc.collect()

                    logger.info(f"AI processing completed with {model_config['model']}")

                    if len(cleaned_content.strip()) > 400:
                        return cleaned_content

                except Exception as e:
                    error_str = str(e).lower()
                    if "429" in str(e) or "quota" in error_str or "rate" in error_str or "exceeded" in error_str:
                        wait_time = min(2 ** retry + random.uniform(0.5, 2), 120)
                        logger.warning(f"Rate limit, retry {retry + 1}/4 after {wait_time:.1f}s")
                        with stats_lock:
                            stats["rate_limit_errors"] += 1
                        if retry < 3:
                            time.sleep(wait_time)
                        continue
                    elif "timeout" in error_str or "deadline" in error_str:
                        logger.warning(f"Timeout with {model_config['model']}, trying next model")
                        with stats_lock:
                            stats["timeout_errors"] += 1
                        break
                    else:
                        logger.error(f"AI processing error with {model_config['model']}: {e}")
                        break

        return None

    finally:
        release_client()


def quality_check_content(content, content_type="html"):
    try:
        if not content or len(content.strip()) < 500:
            return False

        quality_score = 0
        content_lower = content.lower()

        law_id_pattern = r'\d{4}\.\s*évi\s*[IVXLCDMivxlcdm]+'
        if re.search(law_id_pattern, content):
            quality_score += 5

        paragraph_marks = len(re.findall(r'\d+\.\s*§', content))
        if paragraph_marks > 5:
            quality_score += 4
        elif paragraph_marks > 2:
            quality_score += 2
        elif paragraph_marks > 0:
            quality_score += 1

        subsection_marks = len(re.findall(r'\(\d+\)\s*bekezdés|\(\d+\)\s*pont', content))
        if subsection_marks > 10:
            quality_score += 3
        elif subsection_marks > 3:
            quality_score += 1

        hungarian_words = len(re.findall(r'\b[a-záéíóöőúüű]{3,}\b', content, re.IGNORECASE))
        if hungarian_words > 300:
            quality_score += 2

        legal_terms_pattern = r'\b(törvény|rendelet|határozat|végzés|jogszabály|bekezdés|szakasz|fejezet|paragrafus|előírás|szabályozás|hatályos|módosítás|jogalkalmazás|bíróság|ítélet|közlöny|eljárás|feltétel|kötelezettség|jogok|felelősség|szankcióiók|büntetés|díj|illeték|költség)\b'
        legal_terms = len(re.findall(legal_terms_pattern, content, re.IGNORECASE))
        if legal_terms > 40:
            quality_score += 4
        elif legal_terms > 20:
            quality_score += 2
        elif legal_terms > 10:
            quality_score += 1

        if re.search(r'^#{1,4}\s+[^\n]+$', content, re.MULTILINE):
            quality_score += 2

        if re.search(r'\|\s*[^\|]+\s*\|\s*[^\|]+\s*\|', content):
            quality_score += 1

        if re.search(r'^[-*]\s+[^\n]+$', content, re.MULTILINE):
            quality_score += 1

        navigation_keywords = ['bejelentkezés', 'regisztráció', 'cookie', 'impresszum', 'sitemap', 'keresés', 'menu', 'navigáció', 'reklám']
        nav_count = sum(1 for kw in navigation_keywords if kw in content_lower)
        if nav_count > 3:
            quality_score -= 3

        html_tags = len(re.findall(r'<[^>]+>', content))
        if html_tags > len(content) / 20:
            quality_score -= 2

        return quality_score >= 6

    except Exception as e:
        logger.error(f"Quality check error: {e}")
        return False


def download_and_process_pdf(pdf_url):
    normalized_url = normalize_url(pdf_url)

    with pdf_lock:
        if normalized_url in visited_pdfs:
            logger.debug(f"PDF already visited: {normalized_url[:60]}")
            return None
        if len(visited_pdfs) >= max_visited_pdfs:
            logger.warning("Max PDFs reached")
            return None
        visited_pdfs.add(normalized_url)

    logger.info(f"PDF processing: {pdf_url[:70]}")

    pdf_file = None
    try:
        response = session_pdf.get(
            pdf_url,
            timeout=pdf_request_timeout,
            verify=True,
            allow_redirects=True
        )

        if response.status_code < 200 or response.status_code >= 300:
            logger.warning(f"PDF download failed ({response.status_code}): {pdf_url[:60]}")
            with stats_lock:
                stats["processing_errors"] += 1
            return None

        content_type = response.headers.get('content-type', '').lower()
        if 'pdf' not in content_type and 'octet' not in content_type:
            logger.warning(f"Not a PDF content-type: {content_type}")
            with stats_lock:
                stats["processing_errors"] += 1
            return None

        try:
            pdf_file = io.BytesIO(response.content)
            pdf_reader = PyPDF2.PdfReader(pdf_file)

            if len(pdf_reader.pages) == 0:
                logger.warning(f"PDF has no pages: {pdf_url[:60]}")
                with stats_lock:
                    stats["processing_errors"] += 1
                return None

            pdf_text = ""
            max_pages = min(len(pdf_reader.pages), pdf_max_pages)

            for page_num in range(max_pages):
                if shutdown_event.is_set():
                    return None

                try:
                    page = pdf_reader.pages[page_num]
                    extracted = page.extract_text()
                    if extracted and len(extracted.strip()) > 20:
                        pdf_text += extracted + "\n\n"
                except Exception as e:
                    logger.warning(f"Page {page_num} extraction failed: {e}")
                    continue

            pdf_text = pdf_text.strip()

            if len(pdf_text) < 600:
                logger.warning(f"PDF content too short ({len(pdf_text)} chars): {pdf_url[:60]}")
                with stats_lock:
                    stats["processing_errors"] += 1
                return None

            cleaned = process_with_ultra_quality_ai(pdf_url, pdf_text, "pdf")

            if cleaned and quality_check_content(cleaned, "pdf"):
                content_hash = calculate_content_hash(cleaned)

                if not content_hash:
                    logger.error(f"Failed to calculate hash for PDF: {pdf_url[:60]}")
                    return None

                with hash_lock:
                    if content_hash in content_hashes:
                        logger.debug(f"Duplicate PDF content: {pdf_url[:60]}")
                        with stats_lock:
                            stats["duplicate_errors"] += 1
                        return None
                    content_hashes.add(content_hash)

                entry = {
                    "text": cleaned,
                    "meta": {
                        "source": pdf_url,
                        "type": "legal_document_pdf",
                        "format": "pdf",
                        "language": "hu",
                        "quality_score": 0.96,
                        "timestamp": datetime.utcnow().isoformat(),
                        "estimated_tokens": estimate_tokens_accurate(cleaned),
                        "content_hash": content_hash,
                        "document_pages": max_pages
                    }
                }
                return entry

            return None

        except PyPDF2.errors.PdfReadError as e:
            logger.error(f"PDF read error: {e}")
            with stats_lock:
                stats["processing_errors"] += 1
            return None

    except requests.exceptions.Timeout:
        logger.error(f"PDF download timeout: {pdf_url[:60]}")
        with stats_lock:
            stats["timeout_errors"] += 1
        return None
    except requests.exceptions.ConnectionError as e:
        logger.error(f"PDF connection error: {e}")
        with stats_lock:
            stats["processing_errors"] += 1
        return None
    except Exception as e:
        logger.error(f"PDF processing error: {e}")
        with stats_lock:
            stats["processing_errors"] += 1
        return None
    finally:
        if pdf_file:
            try:
                pdf_file.close()
            except:
                pass
        gc.collect()


def extract_njt_pdf_links(soup):
    pdf_links = set()

    try:
        for link in soup.find_all('a', href=True):
            href = link.get('href', '').strip()
            if href.lower().endswith('.pdf') or 'pdf' in href.lower():
                if href.startswith('http://') or href.startswith('https://'):
                    pdf_links.add(normalize_url(href))
                elif href.startswith('/'):
                    pdf_links.add(normalize_url(f""))

        for element in soup.find_all(['a', 'button', 'div'], class_=['pdf-link', 'pdf-download', 'download-pdf', 'letoltes', 'pdf']):
            href = element.get('href') or element.get('data-href')
            if href:
                href = href.strip()
                if 'pdf' in href.lower():
                    if href.startswith('http'):
                        pdf_links.add(normalize_url(href))
                    elif href.startswith('/'):
                        pdf_links.add(normalize_url(f""))

    except Exception as e:
        logger.error(f"PDF link extraction error: {e}")

    return pdf_links


def get_all_njt_links(url, base_domain, max_urls_per_page=150):
    try:
        response = session_html.get(
            url,
            timeout=request_timeout,
            verify=True,
            allow_redirects=True
        )

        if response.status_code < 200 or response.status_code >= 300:
            logger.warning(f"Link extraction failed ({response.status_code}): {url[:60]}")
            return set(), set()

        if response.encoding is None:
            response.encoding = 'utf-8'

        soup = BeautifulSoup(response.content, 'html.parser')

        links = set()
        pdf_links = extract_njt_pdf_links(soup)

        for link in soup.find_all('a', href=True):
            if shutdown_event.is_set():
                break

            href = link.get('href', '').strip()

            if not href or href.startswith(('javascript:', '#', 'mailto:', 'tel:', 'data:')):
                continue

            try:
                full_url = urljoin(url, href)
                normalized_full = normalize_url(full_url)
                parsed = urlparse(normalized_full)

                domain_parts = parsed.netloc.split('.')
                base_parts = base_domain.split('.')

                if parsed.netloc == base_domain or parsed.netloc.endswith('.' + base_domain):
                    path_lower = parsed.path.lower()

                    exclude_patterns = [
                        'login', 'logout', 'bejelentkezes', 'kijelentkezes',
                        'register', 'regisztracio', 'captcha', 'ajax', 'api',
                        'cdn', 'static', 'assets', 'images', 'css', 'js',
                        'fonts', '.jpg', '.png', '.gif', '.webp', '.svg',
                        '.css', '.js', '.ico', '.woff', '.ttf', '.eot',
                        'facebook', 'twitter', 'linkedin', 'youtube',
                        'instagram', 'pinterest', 'export', 'print',
                        'share', 'bookmark', 'download-all'
                    ]

                    if any(pattern in path_lower for pattern in exclude_patterns):
                        continue

                    if len(normalized_full) < 2048:
                        links.add(normalized_full)

            except Exception as e:
                logger.debug(f"Link processing error: {e}")
                continue

        return links, pdf_links

    except requests.exceptions.Timeout:
        logger.error(f"Link extraction timeout: {url[:60]}")
        return set(), set()
    except requests.exceptions.ConnectionError as e:
        logger.error(f"Link extraction connection error: {e}")
        return set(), set()
    except Exception as e:
        logger.error(f"Link extraction error: {e}")
        return set(), set()


def save_entry_to_file(entry):
    try:
        with managed_locks(file_write_lock, output_lock, stats_lock):
            with open(output_file, 'a', encoding='utf-8') as f:
