def crawl_page(url):
    normalized_url = normalize_url(url)

    with url_lock:
        if normalized_url in visited_urls:
            logger.debug(f"URL already visited: {normalized_url[:60]}")
            return None
        if len(visited_urls) >= max_visited_urls:
            logger.warning("Max URLs reached")
            return None
        visited_urls.add(normalized_url)

    logger.info(f"[{len(visited_urls)}/{max_visited_urls}] Processing: {url[:70]}")

    try:
        response = session_html.get(
            url,
            timeout=request_timeout,
            verify=True,
            allow_redirects=True
        )

        if response.status_code < 200 or response.status_code >= 300:
            logger.warning(f"Crawl failed ({response.status_code}): {url[:60]}")
            with stats_lock:
                stats["processing_errors"] += 1
            return None

        if response.encoding is None:
            response.encoding = 'utf-8'

        soup = BeautifulSoup(response.content, 'html.parser')

        metadata = extract_njt_metadata(soup, url)
        html_text = clean_njt_content(soup)

        if len(html_text) < 500:
            logger.debug(f"HTML content too short: {url[:60]}")
            with stats_lock:
                stats["processing_errors"] += 1
            return None

        cleaned = process_with_ultra_quality_ai(url, html_text, "html", metadata)

        if cleaned and quality_check_content(cleaned, "html"):
            content_hash = calculate_content_hash(cleaned)

            if not content_hash:
                logger.error(f"Failed to calculate hash: {url[:60]}")
                return None

            with hash_lock:
                if content_hash in content_hashes:
                    logger.debug(f"Duplicate HTML content: {url[:60]}")
                    with stats_lock:
                        stats["duplicate_errors"] += 1
                    return None
                content_hashes.add(content_hash)

            entry = {
                "text": cleaned,
                "meta": {
                    "source": url,
                    "type": "legal_content_njt",
                    "format": "html",
                    "language": "hu",
