                    "law_type": metadata.get('law_type', ''),
                    "date": metadata.get('date', ''),
                    "section": metadata.get('section', '')
                }
            }

            save_entry_to_file(entry)

            logger.info(f"Saved! Total: {stats['total_entries']} | HTML: {stats['html_pages']} | PDF: {stats['pdfs']} | Tokens: ~{stats['total_tokens_estimate']:,}")

            return entry

        return None

    except requests.exceptions.Timeout:
        logger.error(f"Crawl timeout: {url[:60]}")
        with stats_lock:
            stats["timeout_errors"] += 1
        return None
    except requests.exceptions.ConnectionError as e:
        logger.error(f"Crawl connection error: {e}")
        with stats_lock:
            stats["processing_errors"] += 1
        return None
    except Exception as e:
        logger.error(f"Crawl error: {e}")
        with stats_lock:
            stats["processing_errors"] += 1
        return None


def worker_url_thread(url_queue, pdf_queue, base_domain):
    while not shutdown_event.is_set():
        try:
            url = url_queue.get(timeout=worker_queue_timeout)

            if url is None:
                url_queue.task_done()
                break

            with url_lock:
                if len(visited_urls) >= max_visited_urls:
                    url_queue.task_done()
                    break

            crawl_page(url)

            new_links, new_pdfs = get_all_njt_links(url, base_domain, max_urls_per_page=150)

            new_links_added = 0
            for link in new_links:
                with url_lock:
                    if link not in visited_urls and len(visited_urls) < max_visited_urls:
                        url_queue.put(link)
                        new_links_added += 1

            if new_links_added > 0:
                logger.debug(f"Added {new_links_added} new URLs from {url[:50]}")

            new_pdfs_added = 0
            for pdf_link in new_pdfs:
                with pdf_lock:
                    if pdf_link not in visited_pdfs and len(visited_pdfs) < max_visited_pdfs:
                        pdf_queue.put(pdf_link)
                        new_pdfs_added += 1

            if new_pdfs_added > 0:
                logger.debug(f"Added {new_pdfs_added} new PDFs")

            url_queue.task_done()

        except queue.Empty:
            continue
        except Exception as e:
            logger.error(f"Worker URL thread error: {e}")
            try:
                url_queue.task_done()
            except:
                pass


def worker_pdf_thread(pdf_queue):
