                            logger.info("URL queue empty, finishing URL processing")
                            break
            else:
                logger.info(f"URLs in queue: {queue_size} | Visited: {visited_count}/{max_visited_urls}")
                time.sleep(10)

        logger.info("Sending shutdown signals to URL workers...")
        for _ in range(url_thread_count):
            url_queue.put(None)

        for i, t in enumerate(url_threads):
            t.join(timeout=thread_join_timeout)
            if t.is_alive():
