                break

            with pdf_lock:
                visited_pdf_count = len(visited_pdfs)
                if visited_pdf_count >= max_visited_pdfs:
                    logger.info(f"Reached max PDFs: {max_visited_pdfs}")
                    break

            pdf_queue_size = pdf_queue.qsize()

            if pdf_queue_size == 0:
                time.sleep(15)
                if pdf_queue.qsize() == 0:
                    with pdf_lock:
                        if len(visited_pdfs) < max_visited_pdfs:
                            logger.info("PDF queue empty, finishing PDF processing")
                            break
            else:
                logger.info(f"PDFs in queue: {pdf_queue_size} | Visited: {visited_pdf_count}/{max_visited_pdfs}")
                time.sleep(10)

        logger.info("Sending shutdown signals to PDF workers...")
        for _ in range(pdf_thread_count):
            pdf_queue.put(None)

        for i, t in enumerate(pdf_threads):
            t.join(timeout=thread_join_timeout)
            if t.is_alive():
                logger.warning(f"PDF worker {i} did not terminate within timeout")

    except Exception as e:
        logger.error(f"Error in crawl_all_njt_parallel: {e}")
        shutdown_event.set()

        for _ in range(url_thread_count):
            try:
                url_queue.put(None)
            except:
                pass

        for _ in range(pdf_thread_count):
            try:
                pdf_queue.put(None)
            except:
                pass

        for t in url_threads + pdf_threads:
            t.join(timeout=10)


